'use client';

import { createField } from '@dawitlabs/pixelfield';
import { useEffect, useRef } from 'react';

export interface MarbleProps {
  className?: string;
  tint?: string;
  seed?: number;
  interactive?: boolean;
}

export function Marble({ className, tint, seed = 0, interactive = true }: MarbleProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const field = createField(canvas, {
      generator: 'noise',
      falloff: 'fill',
      scale: 1.3,
      aspect: 1,
      warp: 2.6,
      contrast: 3,
      mode: 'ridged',
      speed: 0.15,
      intensity: 1,
      flow: { x: 0, y: 0 },
      seed,
      tint,
      interactive,
    });
    return () => field.destroy();
  }, [tint, seed, interactive]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}

import { createField } from '@dawitlabs/pixelfield';

export function mountMarble(canvas, { tint, seed = 0, interactive = true } = {}) {
  return createField(canvas, {
      generator: 'noise',
      falloff: 'fill',
      scale: 1.3,
      aspect: 1,
      warp: 2.6,
      contrast: 3,
      mode: 'ridged',
      speed: 0.15,
      intensity: 1,
      flow: { x: 0, y: 0 },
    seed,
    tint,
    interactive,
  });
}
